<?php
/**
 * Reads the `X-Generator` header of a translation file without loading it.
 *
 * Used by the inventory to tell which translation files shipped inside a
 * plugin or theme folder were generated by Babilim. Only small byte ranges
 * are read, and a `.l10n.php` file is never included: the inventory covers
 * components that are not active, and their PHP must not be executed.
 *
 * @package Babilim
 */

declare(strict_types=1);

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Header reader for `.mo` and `.l10n.php` translation files.
 */
final class Babilim_Translation_Header {

	/**
	 * Most bytes a single read may ask for.
	 *
	 * @var int
	 */
	private const MAX_READ = 8192;

	/**
	 * Size of the fixed `.mo` file header, in bytes.
	 *
	 * @var int
	 */
	private const MO_HEADER_SIZE = 28;

	/**
	 * Little-endian `.mo` magic number.
	 *
	 * @var int
	 */
	private const MO_MAGIC = 0x950412de;

	/**
	 * The value of the file's `X-Generator` header, trimmed.
	 *
	 * @param string   $path Path of the file; its extension picks the format.
	 * @param callable $read `fn( string $path, int $offset, int $length ): string`.
	 * @return string The value, or '' when there is none or it can't be read. Never throws.
	 */
	public static function generator( string $path, callable $read ): string {
		try {
			if ( '.l10n.php' === substr( $path, -9 ) ) {
				return self::from_l10n_php( $path, $read );
			}
			if ( '.mo' === substr( $path, -3 ) ) {
				return self::from_mo( $path, $read );
			}
		} catch ( \Throwable $e ) {
			return '';
		}
		return '';
	}

	/**
	 * Header key of a `.l10n.php` file: only the text before the first
	 * `messages` key counts, so a message can't pose as the header.
	 *
	 * @param string   $path Path.
	 * @param callable $read Reader.
	 * @return string
	 */
	private static function from_l10n_php( string $path, callable $read ): string {
		$bytes = (string) call_user_func( $read, $path, 0, self::MAX_READ );
		if ( 1 === preg_match( '/[\'"]messages[\'"]/', $bytes, $m, PREG_OFFSET_CAPTURE ) ) {
			$bytes = substr( $bytes, 0, (int) $m[0][1] );
		}
		if ( 1 !== preg_match( '/[\'"]x-generator[\'"]\s*=>\s*[\'"]([^\'"\\\\]*)[\'"]/i', $bytes, $m ) ) {
			return '';
		}
		return trim( $m[1] );
	}

	/**
	 * Header entry of a little-endian `.mo` file.
	 *
	 * @param string   $path Path.
	 * @param callable $read Reader.
	 * @return string
	 */
	private static function from_mo( string $path, callable $read ): string {
		$head = self::read_exact( $read, $path, 0, self::MO_HEADER_SIZE );
		if ( null === $head ) {
			return '';
		}
		$words = unpack( 'V7', $head );
		if ( ! is_array( $words ) || self::MO_MAGIC !== $words[1] ) {
			return '';
		}
		$orig_table  = (int) $words[4];
		$trans_table = (int) $words[5];

		$orig = self::read_exact( $read, $path, $orig_table, 8 );
		if ( null === $orig ) {
			return '';
		}
		$orig_entry = unpack( 'V2', $orig );
		if ( ! is_array( $orig_entry ) || 0 !== $orig_entry[1] ) {
			return '';
		}

		$trans = self::read_exact( $read, $path, $trans_table, 8 );
		if ( null === $trans ) {
			return '';
		}
		$trans_entry = unpack( 'V2', $trans );
		if ( ! is_array( $trans_entry ) ) {
			return '';
		}
		$length = min( (int) $trans_entry[1], self::MAX_READ );
		if ( $length <= 0 ) {
			return '';
		}
		$block = self::read_exact( $read, $path, (int) $trans_entry[2], $length );
		if ( null === $block ) {
			return '';
		}

		foreach ( explode( "\n", $block ) as $line ) {
			$colon = strpos( $line, ':' );
			if ( false === $colon ) {
				continue;
			}
			if ( 0 === strcasecmp( trim( substr( $line, 0, $colon ) ), 'X-Generator' ) ) {
				return trim( substr( $line, $colon + 1 ) );
			}
		}
		return '';
	}

	/**
	 * A read that must return exactly $length bytes.
	 *
	 * @param callable $read   Reader.
	 * @param string   $path   Path.
	 * @param int      $offset Offset.
	 * @param int      $length Length.
	 * @return string|null Null when the file gave fewer bytes (a range outside the file).
	 */
	private static function read_exact( callable $read, string $path, int $offset, int $length ): ?string {
		if ( $offset < 0 || $length > self::MAX_READ ) {
			return null;
		}
		$bytes = (string) call_user_func( $read, $path, $offset, $length );
		return strlen( $bytes ) === $length ? $bytes : null;
	}
}
